effect.shader:
vec3 u_xlat0;
bool u_xlatb0;
vec3 u_xlat1;
void main()
{
    u_xlat0.xyz = texture(inputImg, acScreenNorm.xy).xyz;
    u_xlat1.xyz = _color_key.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat1.xyz = _color_key.xyz * u_xlat1.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat0.xyz = (-_color_key.xyz) * u_xlat1.xyz + u_xlat0.xyz;
    u_xlat0.x = dot(u_xlat0.xyz, u_xlat0.xyz);
    u_xlat0.x = sqrt(u_xlat0.x);
    u_xlatb0 = u_xlat0.x<_color_threshold;
    if(u_xlatb0){
        fragColor = vec4(1.0, 1.0, 1.0, 1.0);
        return;
    }
    fragColor = vec4(0.0, 0.0, 0.0, 0.0);
    return;
}
